fn solve(a: i8, b: i8) -> (i8, i8) {
    // We want x and y such that:
    //   a = x + y
    //   b = x - y
    //
    // Solve the system:
    //   x = (a + b) / 2
    //   y = (a - b) / 2
    //
    // To avoid overflow when adding/subtracting two i8s, we promote to i16 first.

    let sum = a as i16 + b as i16;
    let diff = a as i16 - b as i16;

    let x = (sum / 2) as i8;
    let y = (diff / 2) as i8;

    (x, y)
}

